-- 124: Original BrillaPrep WASSCE Islamic Religious Studies syllabus evidence beta questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_001', 'topic_was_irs_1', 'subj_wassce_irs', 'exam_wassce', 'What does wahy mean in the context of the Qur’an?', 'multiple_choice', '["A. Divine revelation communicated by Allah to a prophet","B. A private opinion of a historian","C. Any poem written in Arabic","D. A ruling made only by a merchant"]', 'A', 'Wahy refers to divine communication to prophets. Muslims believe the Qur’an was revealed to Prophet Muhammad through the angel Jibril. Therefore the correct answer is A: Divine revelation communicated by Allah to a prophet.', 'easy', 1, 1, 90, 'st_was_irs_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_002', 'topic_was_irs_1', 'subj_wassce_irs', 'exam_wassce', 'Which caliph initiated the first official collection of the Qur’an into one compilation after many reciters died?', 'multiple_choice', '["A. Uthman ibn Affan","B. Abu Bakr","C. Umar ibn Abd al-Aziz","D. Ali ibn Abi Talib"]', 'B', 'Abu Bakr authorised the collection after the Battle of Yamamah, with Zayd ibn Thabit leading the careful compilation work. Therefore the correct answer is B: Abu Bakr.', 'medium', 2, 2, 90, 'st_was_irs_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_003', 'topic_was_irs_1', 'subj_wassce_irs', 'exam_wassce', 'Why did Caliph Uthman distribute standard copies of the Qur’an?', 'multiple_choice', '["A. To add new chapters","B. To translate the text into only one local language","C. To preserve unity in recitation and prevent disputes over written forms","D. To replace memorisation with trade records"]', 'C', 'As Islam spread, differences in recitation practice risked dispute. Standard copies based on the established compilation protected textual unity. Therefore the correct answer is C: To preserve unity in recitation and prevent disputes over written forms.', 'hard', 1, 1, 90, 'st_was_irs_1', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_004', 'topic_was_irs_1', 'subj_wassce_irs', 'exam_wassce', 'What central moral duty appears in Qur’an 17:23 alongside worshipping Allah alone?', 'multiple_choice', '["A. Avoiding all lawful work","B. Refusing hospitality to travellers","C. Keeping knowledge secret","D. Showing kindness and respect to parents"]', 'D', 'The passage joins monotheism with excellent treatment of parents, especially patience, respectful speech and care when they are old. Therefore the correct answer is D: Showing kindness and respect to parents.', 'easy', 2, 2, 90, 'st_was_irs_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_005', 'topic_was_irs_1', 'subj_wassce_irs', 'exam_wassce', 'What is a surah in the Qur’an?', 'multiple_choice', '["A. A chapter of the Qur’an","B. A transmitter in a Hadith chain","C. A voluntary charity only","D. A school of architecture"]', 'A', 'The Qur’an is organised into chapters called suwar, each containing verses called ayat and identified by an established name. Therefore the correct answer is A: A chapter of the Qur’an.', 'medium', 3, 3, 90, 'st_was_irs_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_006', 'topic_was_irs_2', 'subj_wassce_irs', 'exam_wassce', 'What is the isnad of a Hadith?', 'multiple_choice', '["A. The main mosque of a city","B. The chain of people who transmitted the report","C. The legal ruling derived from trade","D. The written chapter heading"]', 'B', 'Hadith scholars examine the isnad to identify transmitters and assess continuity and reliability alongside analysis of the reported text. Therefore the correct answer is B: The chain of people who transmitted the report.', 'hard', 2, 2, 90, 'st_was_irs_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_007', 'topic_was_irs_2', 'subj_wassce_irs', 'exam_wassce', 'What is the matn of a Hadith?', 'multiple_choice', '["A. The chain of transmitters","B. A tax on agricultural produce","C. The actual reported wording or content","D. The direction of prayer"]', 'C', 'A Hadith has a chain of transmission and a reported text. Both require examination when scholars assess authenticity and meaning. Therefore the correct answer is C: The actual reported wording or content.', 'easy', 1, 1, 90, 'st_was_irs_2', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_008', 'topic_was_irs_2', 'subj_wassce_irs', 'exam_wassce', 'Which description best fits a sahih Hadith?', 'multiple_choice', '["A. Every story circulated without a chain","B. A report known to contain a fabricated narrator","C. Any statement that agrees with personal preference","D. A report meeting strong conditions of continuity and reliable transmission"]', 'D', 'Sahih classification depends on connected transmission, trustworthy precise narrators and freedom from disqualifying irregularity or hidden defect. Therefore the correct answer is D: A report meeting strong conditions of continuity and reliable transmission.', 'medium', 2, 2, 90, 'st_was_irs_2', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_009', 'topic_was_irs_2', 'subj_wassce_irs', 'exam_wassce', 'How does Sunnah differ from an individual Hadith report?', 'multiple_choice', '["A. Sunnah is the Prophet’s normative example, while Hadith reports transmit information about it","B. Sunnah is a chapter of the Qur’an","C. Hadith is always later custom with no chain","D. The two terms refer only to buildings"]', 'A', 'Hadith is a vehicle through which sayings, actions and approvals are reported, while Sunnah describes the Prophetic model followed in Muslim life. Therefore the correct answer is A: Sunnah is the Prophet’s normative example, while Hadith reports transmit information about it.', 'hard', 1, 1, 90, 'st_was_irs_2', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_010', 'topic_was_irs_2', 'subj_wassce_irs', 'exam_wassce', 'Why was Umar ibn Abd al-Aziz important in Hadith history?', 'multiple_choice', '["A. He prohibited all written scholarship","B. He ordered scholars to collect Hadith before knowledge and transmitters were lost","C. He replaced the Qur’an with biographies","D. He was the first caller to prayer in Makkah"]', 'B', 'His official encouragement helped move Hadith collection toward organised preservation at a time when knowledgeable transmitters were disappearing. Therefore the correct answer is B: He ordered scholars to collect Hadith before knowledge and transmitters were lost.', 'easy', 3, 3, 90, 'st_was_irs_2', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.', 'https://www.waeconline.org.ng/e-learning/Islamic/IRKmain.html', 0, 1 FROM questions WHERE id BETWEEN 'q_was_irs_b001_001' AND 'q_was_irs_b001_010';
